const jsHooks = String.raw`
const hooks = {
  portada: (step, el, { entered }) => {
    const m = $(".mascot", el);

    if (!entered) {
      return;
    }

    // Tied to the visit, not the render: the re-render after the web fonts load must not cut the typing
    const token = visit;
    m.classList.remove("enter");
    m.style.opacity = 0;
    $(".typed2", el).textContent = "";

    typeInto($(".typed", el), "Pi:", 110, token, () => visit)
      .then(() => typeInto($(".typed2", el), "el agente que se construye solo", 55, token, () => visit))
      .then(() => {
        if (token !== visit) {
          return;
        }

        m.style.opacity = 1;
        m.classList.add("enter");
      });
  },

  demo: (step, el) => setMood($(".mascot", el), step >= 3 ? "wow" : "joy"),

  entornos: (step, el) => $(".machine", el).classList.toggle("away", step >= 3),
};

`;
const html = cssBase + cssBlk + cssMine + '\n/* ───────────── HUD' + cssHud.slice('/* ───────────── HUD'.length) + '</style>\n</head>\n<body>\n' + body + '\n' + jsMascot + jsHooksBase + jsHooks + jsNav;
const out = R+'/.scratch/session-5/prototypes/deck.html';
await $`mkdir -p ${R}/.scratch/session-5/prototypes`;
await write(out, html);
({bytes: html.length, tentacles: /tentacle/i.test(html), scripts: (html.match(/<script>/g)||[]).length})

