const steps=[0,4,3,3,5,2,9,4,5,8,4,3,4,5,2,3,5,4];
const shotDir='/tmp/claude-1000/-home-agus-workspace-filadd-agentic-engineering-famaf-extension-course/b57d1c55-c2ad-4c07-9fbe-ffab3826ec7f/scratchpad/shots';
await $`mkdir -p ${shotDir}`;
const chk = `(() => { const s = document.querySelector(".slide.active"); const k = s.getBoundingClientRect(); const bad = []; s.querySelectorAll("*").forEach(e => { const r = e.getBoundingClientRect(); if (r.width === 0) return; if (r.right > k.right + 2 || r.bottom > k.bottom + 2 || r.left < k.left - 2 || r.top < k.top - 2) bad.push((e.className.baseVal ?? e.className) + "|" + e.tagName + " r" + Math.round(r.right - k.right) + " b" + Math.round(r.bottom - k.bottom)); if (e.scrollWidth > e.clientWidth + 2 && getComputedStyle(e).overflow !== "visible") bad.push("clip:" + e.className + " " + e.scrollWidth + ">" + e.clientWidth); }); return JSON.stringify(bad.slice(0, 8)); })()`;
const report={};
for (let i=0;i<steps.length;i++){
  await ab('open', url+'#'+(i+1)+(steps[i]?'.'+steps[i]:''));
  await sleep(i===0?4500:1800);
  const r = await ab('eval', chk);
  report[i+1]=r.stdout.trim().split('\n').pop();
  await ab('screenshot', `${shotDir}/s${String(i+1).padStart(2,'0')}.png`);
}
report

