const chat = (()=>{const i=talkHtml.indexOf('ChatGPT'); return i<0?null:talkHtml.slice(i-100,i+600);})();
({list, refs, chat, scripts: [...talkHtml.matchAll(/<script[^>]*>/g)].map(m=>m[0])})

