rep(`<span class="ys">y si…</span> varias personas siguen y dirigen la misma sesión`, `<span class="ys">y si…</span> varias personas pudieran seguir y dirigir la misma sesión`);
rep(`un agente general como el coding agent está pensado`, `un agente como el coding agent está pensado`);

const col = (n, name, ca, pd) => `
      <div class="vh" data-step="${n}">${name}</div>
      <div class="vc ca" data-step="${n}" style="grid-row: 2">${ca}</div>
      <div class="vc pd" data-step="${n}" style="grid-row: 3">${pd}</div>`;
const slide = `
  <!-- 18 · Coding agent vs pi-durable -->
  <section class="slide" data-id="versus">
    <h2>Coding agent vs pi-durable</h2>
    <div class="vs-grid">
      <div class="vl" style="grid-row: 2"><i class="dot ca"></i>coding agent</div>
      <div class="vl" style="grid-row: 3"><i class="dot pd"></i>pi-durable</div>${col(1, '💾 Storage', 'un JSONL en <code>~/.pi/agent/sessions</code>', 'memoria, IndexedDB, SQLite, JSONL, Durable Object')}${col(2, '🛰️ Entorno de ejecución', 'la máquina donde corre el proceso', '<code>env()</code> en cada llamada: directorio local, contenedor, VM remota')}${col(3, '⏳ Durabilidad', 'si el proceso muere, mirás y le decís que siga', 'cada efecto con checkpoint; <code>resume()</code> retoma donde quedó')}${col(4, '👥 Multiplayer', 'una persona, una terminal', 'varios clientes: watch, steer, follow-up')}
    </div>
  </section>
  <!-- Notas: el cierre del bloque, aspecto por aspecto en el mismo orden de las slides: storage, entorno de ejecución, durabilidad, multiplayer. No es que uno sea mejor que el otro: pi-durable no reemplaza al coding agent. Son respuestas distintas a las mismas decisiones de diseño: dónde se guarda la sesión, dónde actúan las tools, qué pasa si el proceso se cae y quién puede seguir y dirigir la conversación. El coding agent elige lo simple para una persona en una terminal; pi-durable paga más complejidad para sostener lo demás. -->
`;
const anchor = '\n</div>\n\n<div id="hud">';
if (h.split(anchor).length !== 2) throw new Error('deck end anchor');
h = h.replace(anchor, () => slide + anchor);
rep(`/* PD6: multiplayer */`, `/* comparación final */
.vs-grid { display: grid; grid-template-columns: 170px repeat(4, 1fr); grid-template-rows: auto 1fr 1fr; gap: 16px 18px; height: 500px; margin-top: 6px; }
.vs-grid .vh { grid-row: 1; padding: 0 4px 4px; font-family: var(--font-display); font-size: 24px; font-weight: 700; }
.vs-grid .vl { grid-column: 1; display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-size: 24px; font-weight: 700; }
.vs-grid .vl .dot { flex: none; width: 22px; height: 22px; border: 3px solid; border-radius: 6px; }
.vs-grid .dot.ca { border-color: var(--a4); background: color-mix(in srgb, var(--a4) 20%, var(--card)); }
.vs-grid .dot.pd { border-color: var(--a1); background: color-mix(in srgb, var(--a1) 22%, var(--card)); }
.vs-grid .vc { display: flex; align-items: center; padding: 16px 18px; font-size: 21px; line-height: 1.35; border: 3px solid; border-radius: 14px; box-shadow: 5px 5px 0 #05051a; }
.vs-grid .vc.ca { border-color: var(--a4); background: color-mix(in srgb, var(--a4) 20%, var(--card)); }
.vs-grid .vc.pd { border-color: var(--a1); background: color-mix(in srgb, var(--a1) 22%, var(--card)); }
.vs-grid code { font-family: var(--font-mono); font-size: 17px; color: var(--a3); }
.vs-grid .vc.pd[data-step] { transition-delay: .15s; }

/* PD6: multiplayer */`);
await write(out, h);

await ab('set','viewport','1600','900');
const st=[0,4,3,3,5,2,9,4,5,8,4,0,4,5,2,6,6,4,4];
await ab('open', url+'#1'); await ab('reload'); await sleep(2500);
const rp={};
for (let i=0;i<st.length;i++){
  for (let k=0;k<st[i];k++){ await ab('press','ArrowRight'); await sleep(120); }
  await sleep(1400);
  rp[i+1]=(await ab('eval','location.hash')).stdout.trim().split('\n').pop()+' '+(await ab('eval', chk)).stdout.trim().split('\n').pop();
  if (i===12||i===18) await ab('screenshot', `${shotDir}/r3_${i+1}.png`);
  await ab('press','ArrowRight'); await sleep(200);
}
const lastHash=(await ab('eval','location.hash')).stdout.trim().split('\n').pop();
await ab('eval', `window.__m = null; addEventListener("message", e => { if (e.data?.type === "kurasu:manifest") window.__m = e.data; }); const f = document.createElement("iframe"); f.style.cssText = "position:fixed;inset:0;width:100%;height:100%;z-index:999"; f.src = location.href.split("#")[0]; document.body.appendChild(f); "ok"`);
await sleep(2500);
const man=(await ab('eval','JSON.stringify(window.__m)')).stdout.trim().split('\n').pop();
await ab('close');
for (const n of [13,19]) await Read({file_path:`${shotDir}/r3_${n}.png`});
({rp, lastHash, man, git: await $`cd ${R} && git status --short`.text()})

